-- Плейофф (хасагдах шат) — нэг улиралд нэг плейофф
-- Supabase SQL Editor дээр нэг удаа ажиллуулна. Давтан ажиллуулахад аюулгүй.
--
-- Цувралын оноо, дараагийн шатанд шилжих багийг хадгалахгүй — stage='playoff'
-- тоглолтуудын үр дүнгээс тооцоолно (src/lib/playoff.ts).

CREATE TABLE IF NOT EXISTS public."playoffs" (
  "id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "season_id" int NOT NULL UNIQUE,
  "team_count" smallint NOT NULL CHECK ("team_count" IN (2,4,8,16)),
  -- Шат бүрийн best-of, эхний шатнаас финал хүртэл таслалаар: "3,3,5"
  "best_of" varchar(40) NOT NULL,
  "created_at" timestamp without time zone DEFAULT public.app_now()
);
ALTER TABLE public."playoffs" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public."playoffs" FROM anon, authenticated;

-- №1..N байранд аль баг байгаа (хоосон байр = эсрэг талын баг шууд дараагийн шатанд)
CREATE TABLE IF NOT EXISTS public."playoff_seeds" (
  "id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "playoff_id" int NOT NULL REFERENCES public."playoffs"("id") ON DELETE CASCADE,
  "seed" smallint NOT NULL,
  "season_team_id" int NOT NULL,
  UNIQUE ("playoff_id", "seed"),
  UNIQUE ("playoff_id", "season_team_id")
);
ALTER TABLE public."playoff_seeds" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public."playoff_seeds" FROM anon, authenticated;
